content.text:
{
 "批": "S09",
 "裁定": [
  {
   "编号": "qs-2-2-216:s001",
   "断语": [
    {
     "条件原文": "巨门命陷",
     "判断原文": "主淫娼"
    },
    {
     "条件原文": "巨门命陷",
     "判断原文": "侍女偏房免灾殃"
    },
    {
     "条件原文": "巨门命陷",
     "判断原文": "相貌清奇"
    },
    {
     "条件原文": "巨门命陷",
     "判断原文": "多近宠"
    },
    {
     "条件原文": "巨门命陷",
     "判断原文": "寿夭或凶亡"
    }
   ],
   "理由": "全句命理条件只有「巨门命陷」一个，后文皆由它带出；「侍女偏房」是人事去向而非星曜宫位等命理条件，故「侍女偏房免灾殃」整句作一条判断（从甲）；「相貌清奇」是长相、「多近宠」是际遇，属一个条件带出两个判断，依 codebook 各算一条（从乙）；「不然寿夭或凶亡」条件同为巨门命陷。"
  },
  {
   "编号": "qs-3-18-7:s001",
   "断语": [
    {
     "条件原文": "戌亥羊陀",
     "判断原文": "须避忌"
    },
    {
     "条件原文": "戌亥生人忌遇羊陀",
     "判断原文": "灾重"
    },
    {
     "条件原文": "戌生人又行到戍宫岁限",
     "判断原文": "为地网"
    },
    {
     "条件原文": "行到辰宫岁限",
     "判断原文": "为天罗"
    },
    {
     "条件原文": "辰戌相冲",
     "判断原文": "不美"
    }
   ],
   "理由": "首句「戌亥羊陀」是生人与所遇之星的条件，「须避忌」才是判断，从乙；第四、五条中「又忌」「谓之」是连接语而非条件，条件原文应为「行到辰宫岁限」「辰戌相冲」，从甲；其余两条二人一致。"
  }
 ]
}

{
 "批": "S03",
 "裁定": [
  {
   "编号": "qs-1-11-1:s001",
   "断语": [
    {
     "条件原文": "天机",
     "判断原文": "南斗第三益算之善星也"
    }
   ],
   "理由": "采甲。「属木」是星曜五行所属的基本属性说明，与星名由来、排盘资料同类，不构成对星的吉凶定性或对人事的判断；「南斗第三益算之善星也」是给天机定名定性，属断语。"
  },
  {
   "编号": "qs-2-1-164:s001",
   "断语": [
    {
     "条件原文": "伏兵",
     "判断原文": "主口舌"
    }
   ],
   "理由": "采甲，与上句同理：「属火」是五行属性说明，不算断语；「主口舌」是对伏兵的定性判断，条件为「伏兵」。"
  },
  {
   "编号": "qs-2-2-107:s001",
   "断语": [
    {
     "条件原文": "人生二限值天同",
     "判断原文": "喜气盈门"
    },
    {
     "条件原文": "人生二限值天同",
     "判断原文": "万事荣"
    },
    {
     "条件原文": "人生二限值天同",
     "判断原文": "财禄增添"
    },
    {
     "条件原文": "人生二限值天同",
     "判断原文": "宜创造"
    },
    {
     "条件原文": "人生二限值天同",
     "判断原文": "从今家道得丰荣"
    }
   ],
   "理由": "采甲。「喜气盈门」与「万事荣」、「财禄增添」与「宜创造」各是独立的判断，按一个条件带出几个判断各算一条的规则分开；与两人在 qs-2-2-100 对「福禄悠悠」「寿更长」的切法一致。"
  },
  {
   "编号": "qs-2-2-425:s001",
   "断语": [
    {
     "条件原文": "女命",
     "判断原文": "性刚"
    },
    {
     "条件原文": "女命",
     "判断原文": "背六亲"
    },
    {
     "条件原文": "女命",
     "判断原文": "伤夫克子"
    },
    {
     "条件原文": "遇吉",
     "判断原文": "始能丰足"
    }
   ],
   "理由": "采甲。「性刚」是性情判断，「背六亲」是六亲判断，内容不同，应各算一条，条件同为「女命」。"
  },
  {
   "编号": "qs-3-19-27:s002",
   "断语": [
    {
     "条件原文": "若遇廉贞破军太阴天相擎羊忌宿",
     "判断原文": "其年破财"
    },
    {
     "条件原文": "若遇廉贞破军太阴天相擎羊忌宿",
     "判断原文": "官灾口舌"
    },
    {
     "条件原文": "若遇廉贞破军太阴天相擎羊忌宿",
     "判断原文": "本身见晦"
    }
   ],
   "理由": "采甲。「减半论之」是对前面诸判断如何取用的论断方法说明，本身不是关于人或事的判断，不另立为断语。"
  },
  {
   "编号": "qs-3-20-35:s001",
   "断语": [
    {
     "条件原文": "天相廉贞擎羊来",
     "判断原文": "多招刑杖难逃"
    },
    {
     "条件原文": "天相廉贞擎羊来",
     "判断原文": "终身不美"
    },
    {
     "条件原文": "天相廉贞擎羊来",
     "判断原文": "招横祸"
    },
    {
     "条件原文": "天相廉贞擎羊来",
     "判断原文": "只宜僧道"
    }
   ],
   "理由": "采甲。「终身不美」与「招横祸」是两个独立判断，同一条件带出，应分列两条。"
  }
 ]
}

{
 "批": "S07",
 "裁定": [
  {
   "编号": "qs-3-18-8:s001",
   "断语": [
    {
     "条件原文": "酉人",
     "判断原文": "陀刃亦非亲"
    },
    {
     "条件原文": "假如酉生人",
     "判断原文": "亦忌羊陀岁限"
    },
    {
     "条件原文": "假如酉生人",
     "判断原文": "忌行卯宫限，及卯年岁君相冲"
    }
   ],
   "理由": "采甲。「亦忌羊陀岁限」与「忌行卯宫限，及卯年岁君相冲」由「及忌」连接，是同一条件（酉生人）带出的两个并列判断，按 codebook 一条件多判断各算一条的规则应分开，乙合为一条不合规则。"
  },
  {
   "编号": "qs-3-19-15:s002",
   "断语": [
    {
     "条件原文": "若遇天同巨门武曲贪狼忌宿太阳擎羊",
     "判断原文": "便断其年人财耗散"
    },
    {
     "条件原文": "若遇天同巨门武曲贪狼忌宿太阳擎羊",
     "判断原文": "官灾口舌孝服"
    },
    {
     "条件原文": "若遇天同巨门武曲贪狼忌宿太阳擎羊",
     "判断原文": "本身遭晦"
    }
   ],
   "理由": "采乙。「减半论之」是对前述诸判断如何取用的推断方法说明（打折论之），不是关于人或事的独立判断，也非给星定名定性，按 codebook 不算断语；其余三条判断两人一致。"
  }
 ]
}

{
 "批": "S10",
 "裁定": [
  {
   "编号": "qs-1-7-19:s001",
   "断语": [
    {
     "条件原文": "人生发达限元",
     "判断原文": "最怕浮沉"
    },
    {
     "条件原文": "命限逢乎驳杂",
     "判断原文": "一世迍邅"
    }
   ],
   "理由": "采乙。本句上下两联对仗，「人生发达限元」是所论对象（条件），「最怕浮沉」是判断，不应把条件并入判断而留空条件；下联两人一致，照录。"
  },
  {
   "编号": "qs-1-30-7:s001",
   "断语": [
    {
     "条件原文": "禄存对向守迁移，三合逢之",
     "判断原文": "利禄宜"
    },
    {
     "条件原文": "禄存对向守迁移，三合逢之",
     "判断原文": "遐迩人钦敬"
    },
    {
     "条件原文": "禄存对向守迁移，三合逢之",
     "判断原文": "的然白手起家基"
    }
   ],
   "理由": "采甲。「得逢」是「若遇此」的条件性承接语，不是判断内容，判断应自「遐迩人钦敬」起抄；三条判断同出一个条件，条件原文相同。"
  },
  {
   "编号": "qs-1-47-10:s001",
   "断语": [
    {
     "条件原文": "夹日夹月",
     "判断原文": "谁能遇"
    },
    {
     "条件原文": "夹昌夹曲",
     "判断原文": "主贵"
    }
   ],
   "理由": "采甲。「兮」为赋体句末语气助词，不属判断内容，判断说完即止于「主贵」；首联两人一致，照录。"
  }
 ]
}

{
 "批": "S08",
 "裁定": [
  {
   "编号": "qs-1-4-3:s002",
   "断语": [
    {
     "条件原文": "贪狼天机",
     "判断原文": "是庙乐"
    },
    {
     "条件原文": "得天相水到寅",
     "判断原文": "为之旺相"
    },
    {
     "条件原文": "巨门水得卯",
     "判断原文": "为之疏通"
    },
    {
     "条件原文": "三方更得文曲水破军水相会",
     "判断原文": "尤妙"
    },
    {
     "条件原文": "又加禄存土",
     "判断原文": "极美矣"
    }
   ],
   "理由": "采乙。「是庙乐」是给贪狼天机二星定性的判断，其条件（二星）就在本句，按 codebook 条件在本句的应抄本句的字，不必从整段前文抄「寅乃木之垣」；其余四条两人一致。"
  },
  {
   "编号": "qs-2-1-151:s001",
   "断语": [
    {
     "条件原文": "化权",
     "判断原文": "属木"
    },
    {
     "条件原文": "化权",
     "判断原文": "喜会巨门武曲"
    }
   ],
   "理由": "采乙。「属木」是给化权星定性之语，属 codebook 所列「给星定名定性」一类断语，不是单讲星名由来，故应单列一条；「喜会巨门武曲」与之同条件、不同判断，各算一条。"
  },
  {
   "编号": "qs-2-2-428:s001",
   "断语": [
    {
     "条件原文": "铃星一宿",
     "判断原文": "不可当"
    },
    {
     "条件原文": "铃星一宿不可当，守临二限",
     "判断原文": "必癫狂"
    },
    {
     "条件原文": "若无吉曜来相照",
     "判断原文": "未免招灾惹祸殃"
    }
   ],
   "理由": "采甲。「一宿」是指称铃星这颗星的主语成分，不是判断内容，判断自「不可当」起，故条件原文应为「铃星一宿」；后两条两人一致。"
  },
  {
   "编号": "qs-2-10-16:s001",
   "断语": [
    {
     "条件原文": "七杀庙旺",
     "判断原文": "武职峥嵘"
    },
    {
     "条件原文": "七杀庙旺",
     "判断原文": "权贵非小"
    },
    {
     "条件原文": "七杀庙旺",
     "判断原文": "不宜文人"
    },
    {
     "条件原文": "武曲同",
     "判断原文": "权贵"
    },
    {
     "条件原文": "廉贞同",
     "判断原文": "功名显达"
    }
   ],
   "理由": "采甲。「武职峥嵘」与「权贵非小」是同一条件带出的两个判断（一说职业、一说地位），按 codebook 一个条件带出几个判断的应各算一条；其余三条两人一致。"
  },
  {
   "编号": "qs-3-20-193:s001",
   "断语": [
    {
     "条件原文": "七杀守照岁限擎羊午生人命安卯西宫",
     "判断原文": "主凶亡"
    },
    {
     "条件原文": "余宫",
     "判断原文": "亦忌命限三合杀"
    },
    {
     "条件原文": "流年羊刃到命",
     "判断原文": "即七杀重逢"
    },
    {
     "条件原文": "申酉宫",
     "判断原文": "忌"
    },
    {
     "条件原文": "申酉宫",
     "判断原文": "多忌限"
    }
   ],
   "理由": "采乙。「申酉宫忌，多忌限」中「忌」与「多忌限」以逗号隔开、各自说完，是同一条件下的两个判断，按 codebook 应分列两条，判断原文不宜跨逗号合抄；前三条两人一致。"
  }
 ]
}

{
 "批": "S02",
 "裁定": [
  {
   "编号": "qs-1-4-1:s001",
   "断语": [
    {
     "条件原文": "紫微帝座",
     "判断原文": "以辅弼为佐"
    },
    {
     "条件原文": "紫微帝座",
     "判断原文": "贰作数中之主星乃有用之源流"
    }
   ],
   "理由": "本句是给紫微定性：「以辅弼为佐」与「作数中之主星乃有用之源流」都是对紫微帝座的定性判断，属一个条件带出两个判断，各算一条；「以辅弼为佐」不是条件而是判断，故采甲。"
  },
  {
   "编号": "qs-1-10-9:s001",
   "断语": [
    {
     "条件原文": "若居官禄身命，三宫",
     "判断原文": "最要左右守卫"
    }
   ],
   "理由": "「三宫」即指官禄、身、命三宫，是宫位条件的一部分，判断本身是「最要左右守卫」，采乙。"
  },
  {
   "编号": "qs-1-10-12:s002",
   "断语": [
    {
     "条件原文": "更与武曲禄存同宫，身命中",
     "判断原文": "尤为奇特"
    }
   ],
   "理由": "「身命中」是宫位条件（在身命宫中），判断只是「尤为奇特」，采乙。"
  },
  {
   "编号": "qs-1-10-23:s001",
   "断语": [
    {
     "条件原文": "三方有吉拱",
     "判断原文": "方作贵人评"
    },
    {
     "条件原文": "若还无辅弼",
     "判断原文": "诸恶共饮凌"
    },
    {
     "条件原文": "若还无辅弼",
     "判断原文": "帝为无道主"
    }
   ],
   "理由": "歌诀两两对仗，「若还无辅弼」与前句「三方有吉拱」同为条件句，「诸恶共饮凌」是无辅弼的后果（帝座受诸恶侵凌），与「帝为无道主」同为判断，采乙；「考究要知因」是提示语，不是断语。"
  },
  {
   "编号": "qs-1-16-2:s008",
   "断语": [
    {
     "条件原文": "天府",
     "判断原文": "不喜四杀冲破"
    },
    {
     "条件原文": "四杀冲破",
     "判断原文": "虽无官贵"
    },
    {
     "条件原文": "四杀冲破",
     "判断原文": "亦主财田富足"
    }
   ],
   "理由": "「虽无官贵」（无官贵）与「亦主财田富足」是同一条件下的两个判断，按一条件带几个判断各算一条的规则拆开，采乙。"
  },
  {
   "编号": "qs-2-2-47:s001",
   "断语": [
    {
     "条件原文": "庙旺",
     "判断原文": "终身富贵"
    },
    {
     "条件原文": "陷地虽化权禄",
     "判断原文": "也凶"
    },
    {
     "条件原文": "陷地",
     "判断原文": "官禄亦不显"
    },
    {
     "条件原文": "陷地",
     "判断原文": "先勤终懒"
    },
    {
     "条件原文": "陷地",
     "判断原文": "成败不一"
    },
    {
     "条件原文": "陷地",
     "判断原文": "出外离祖可吉"
    }
   ],
   "理由": "「虽化权禄」是让步条件，判断是「也凶」，此处从乙；其后数条判断仍以「陷地」为条件，「虽化权禄」只管「也凶」一句；「出外离祖可吉」是陷地之下的整体判断（宜离祖出外），「出外离祖」不是命理条件，此处从甲。"
  },
  {
   "编号": "qs-2-2-294:s001",
   "断语": [
    {
     "条件原文": "破军七杀与贪狼，入庙",
     "判断原文": "英雄不可当"
    },
    {
     "条件原文": "破军七杀与贪狼，入庙",
     "判断原文": "关羽命逢为上将"
    },
    {
     "条件原文": "破军七杀与贪狼，入庙",
     "判断原文": "庶人富足置田庄"
    }
   ],
   "理由": "三句都是「破军七杀与贪狼，入庙」这一命理条件带出的判断；「关羽命逢」「庶人」是举例与人群分述，不是星曜宫位条件，不宜作条件原文，采乙。"
  },
  {
   "编号": "qs-2-2-413:s001",
   "断语": [
    {
     "条件原文": "限遇陀罗",
     "判断原文": "事亦多"
    },
    {
     "条件原文": "限遇陀罗",
     "判断原文": "必然忍耐要谦和"
    },
    {
     "条件原文": "若无吉曜同相会",
     "判断原文": "须教一梦入南柯"
    }
   ],
   "理由": "「必然忍耐要谦和」是由限遇陀罗推出的处境判断（须忍耐谦和方可），与「须防脓血」「出外离祖可吉」一类同属断语，不应漏掉，采甲。"
  },
  {
   "编号": "qs-2-6-17:s001",
   "断语": [
    {
     "条件原文": "天机同",
     "判断原文": "劳心用力发财不多"
    },
